package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** The figure a claim shows and totals: the due fixed when it was settled, else the greater of the
 *  sheet's floor in force on the claim's date and its figure, plus the late charge on that, where its figure is
 *  the one its person's last statement bound it to, else live at its person's grade's rate in force on
 *  the claim's date (null, n/a, when there is no rate). A correction has neither floor nor charge. Every rounding of a claim's live figures follows
 *  the sheet's rounding mode in force on the claim's date, else the sheet's policy date: half up for a claim dated before it, half to even on or after it. */
@Service
public class Figures {

    private final Rates rates;
    private final Settings settings;
    private final Sheets sheets;
    private final Claims claims;

    public Figures(Rates rates, Settings settings, Sheets sheets, Claims claims) {
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
        this.claims = claims;
    }

    /** The sheet's policy date: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = settings.policyDate(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** How the claim's live figures round: by the sheet's rounding mode in force on the claim's
     *  (rounding) date when one is; else half up when the claim is dated before the sheet's policy
     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
    public RoundingMode rounding(Claim claim) {
        RoundingMode set = settings.rounding(claim.getSheetId(), roundingDate(claim));
        if (set != null) return set;
        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate roundingDate(Claim claim) {
        if (claim.getCorrects() == null) return claim.getDate();
        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
        return corrected != null ? corrected : claim.getDate();
    }

    /** The claim's due as the screen shows and totals it: its figure raised to the sheet's floor in
     *  force on the claim's date when it is below it, plus the late charge on that floored figure while
     *  it is overdue (a correction has neither). A settled claim's fixed due already holds the charge and floor it had then;
     *  a claim bound by a statement shows the due bound then, its late charge no longer following today. */
    public BigDecimal due(Claim claim, String grade) {
        BigDecimal figure = figure(claim, grade);
        if (figure == null || claim.getDue() != null || claim.isStated() || claim.isCorrection()) return figure;
        BigDecimal floored = figure.max(settings.floor(claim.getSheetId(), claim.getDate()));
        return floored.add(charge(claim, grade, floored));
    }

    /** The claim's figure: the fixed due, else the bound due (with the late charge and floor it had when
     *  bound), else live without any late charge or floor.
     *  A PENDING claim is bound by a statement like any other: it shows its bound figure. */
    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated()) return claim.getStatedDue();
        return live(claim, grade);
    }

    /** The date the claim goes overdue after: its due-by (fixed when it was added) plus the grace days
     *  of its person's grade in force on the claim's date (`grade`), in force on that date. */
    public LocalDate overdueFrom(Claim claim, String grade) {
        return claim.getDueBy().plusDays(settings.grace(claim.getSheetId(), grade, claim.getDate()));
    }

    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, and its due-by plus its grace
     *  (see {@link #overdueFrom}) is before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        if (!claim.getStatus().isOpen() || claim.isDeferred()) return false;
        LocalDate today = sheets.today(claim.getSheetId());
        return today != null && overdueFrom(claim, grade).isBefore(today);
    }

    /** The late charge on a figure of the claim: nothing unless the claim is OPEN (or PENDING), not deferred, and its due-by (fixed
     *  when it was added) plus its grace is before the sheet's today (a correction, or a claim whose charge is waived, has none); then, for every full 30 days it is
     *  overdue, counted from its due-by plus its grace, the sheet's late percent in force on that boundary date (the due-by plus
     *  the grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each rounded by the claim's rounding to two decimals, added up. A
     *  boundary whose percent is 0.00 adds nothing. It follows the sheet's today; a statement binds it into the claim's due (see {@link #due}). */
    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.getStatus().isOpen() || claim.isDeferred() || claim.isCorrection() || claim.isWaived()) return none;
        String sheetId = claim.getSheetId();
        LocalDate from = overdueFrom(claim, grade);
        long periods = ChronoUnit.DAYS.between(from, sheets.today(sheetId)) / 30;
        BigDecimal total = none;
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * k));
            if (pct.signum() == 0) continue;
            total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim)));
        }
        return total;
    }

    /** A share holder's part of the claim, `grade` the holder's own grade in force on the claim's date:
     *  for a settled claim the part frozen with its fixed due (see {@link ClaimShare#partOf}), else the
     *  claim's amount times the share divided by 100, times the rate of that grade in force on the
     *  claim's date divided by 100, rounded by the claim's rounding to two decimals; null (a part of
     *  0.00) when that grade has no rate. */
    public BigDecimal part(Claim claim, ClaimShare share, String grade) {
        if (claim.getDue() != null) return share.partOf(claim.getDue());
        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate(), claim.seq());
        if (pct == null) return null;
        return claim.getAmount().multiply(share.share()).multiply(pct).divide(BigDecimal.valueOf(10000))
                .setScale(2, rounding(claim));
    }

    /** The claim's due at its person's grade's rate in force on the claim's date (passing over a
     *  forward-only rate saved after the claim was added, see {@link Rates#ownPct}): amount times the
     *  rate divided by 100, rounded by the claim's rounding to two decimals, before any late charge or
     *  floor (see {@link #due}); null when there is no rate. */
    public BigDecimal live(Claim claim, String grade) {
        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate(), claim.seq());
        if (pct == null) return null;
        return claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** A claim a person on a sheet has made, DRAFT (and unnumbered) until it is opened. `id` is null until the claim is first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal due;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private boolean deferred;
    private int proofs;
    private int proofPhotos;
    private String splitFrom;
    private String lockedBy;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private boolean escalated;
    private boolean escalatedNow;
    private boolean waived;
    private boolean held;
    private String reviewAssigned;
    private String ref;
    private String tags;
    private String tagsUsed;
    private String voidReason;
    private String editedBy;
    private Integer dueTerms;
    private Integer batch;
    private Long addedSeq;
    private List<ClaimShare> shares = List.of();

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.due = due;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on its sheet, given when it is settled or approved (sheet-wide "7", or within its period "P1-2" / "X-1"); null until then (a claim numbered when opened, before numbering moved to settlement, keeps that number). A voided claim keeps its number. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when the claim was settled; null when it has none (not settled, or settled with no rate). */
    public BigDecimal getDue() { return due; }
    public void setDue(BigDecimal due) { this.due = due; }
    /** The user who opened the claim; null while it has not been opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether the claim is bound by its person's last statement to the figure it had then. */
    public boolean isStated() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    /** The figure the last statement bound the claim to; null when unbound, or bound to n/a. */
    public BigDecimal getStatedDue() { return statedDue; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    /** The number of the SETTLED claim of the same person this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** The date the claim is due by, fixed when it was added: its date then plus the terms of its
     *  person's grade in force on that date. Later changes to the terms or the claim's date leave it;
     *  a holiday added on or before it re-fixes it (unless SETTLED or VOID) from its date, with the same terms.
     *  A steward may set it directly; it then keeps no terms and stays as set. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The terms (business days) the claim's due-by was fixed with; a holiday added re-fixes it with these;
     *  null when its due-by was set directly, so it is never re-fixed. */
    public Integer getDueTerms() { return dueTerms; }
    public void setDueTerms(Integer dueTerms) { this.dueTerms = dueTerms; }
    /** The date the claim was last deferred until; null when it never was. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /** Whether the claim is deferred now: the sheet's today (as it was when the claim was read) is
     *  before its deferred-until date (only an OPEN claim is deferred, and a voided one keeps showing
     *  it), and no statement binds it: a deferral of a bound claim takes effect only once the binding
     *  ends (the statement is cancelled, or the next statement leaves it unbound). A deferred claim
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferred() { return deferred && !stated; }
    public void setDeferred(boolean deferred) { this.deferred = deferred; }
    /** How many proofs the claim has: a claim whose due is above the sheet's proof threshold on its
     *  date cannot be settled or approved while it has none. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** How many of the claim's proofs are photos; the rest are receipts. */
    public int getProofPhotos() { return proofPhotos; }
    public void setProofPhotos(int proofPhotos) { this.proofPhotos = proofPhotos; }
    /** How many of the claim's proofs are of this kind (receipt or photo). */
    public int proofsOf(String kind) {
        return ProofKind.PHOTO.equals(kind) ? proofPhotos : ProofKind.RECEIPT.equals(kind) ? proofs - proofPhotos : 0;
    }
    /** The number of the claim this one was split off; null when it was not split off one. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Whether the claim was added while its period was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The last day (sheet-today) a reminder was written for the claim; null when it never was. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** Whether the claim has been escalated by a reminder: at most once, ever. */
    public boolean isEscalated() { return escalated; }
    public void setEscalated(boolean escalated) { this.escalated = escalated; }
    /** Whether the reminder being taken now escalates the claim (not stored). */
    public boolean isEscalatedNow() { return escalatedNow; }
    public void setEscalatedNow(boolean escalatedNow) { this.escalatedNow = escalatedNow; }
    /** Whether a steward has waived the claim's late charge: it bears none from then on, whatever its overdue state. */
    public boolean isWaived() { return waived; }
    public void setWaived(boolean waived) { this.waived = waived; }
    /** Whether the claim is held: shown only; it still counts in every total. */
    public boolean isHeld() { return held; }
    public void setHeld(boolean held) { this.held = held; }
    /** The user a steward assigned the claim's review to; null when none. */
    public String getReviewAssigned() { return reviewAssigned; }
    public void setReviewAssigned(String reviewAssigned) { this.reviewAssigned = reviewAssigned; }
    /** The claim's external reference, unique on its sheet without regard to case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** The claim's tags, lower-cased, sorted and comma separated; null when it has none. */
    public String getTags() { return tags; }
    /** Sets the claim's tags, adding them to the tags it has ever carried. */
    public void setTags(String tags) {
        this.tags = tags;
        this.tagsUsed = ClaimRequest.union(tagsUsed, tags);
    }
    /** Every tag the claim has ever carried, in the same form as its tags; null when none. */
    public String getTagsUsed() { return tagsUsed; }
    public void setTagsUsed(String tagsUsed) { this.tagsUsed = tagsUsed; }
    /** The reason from its sheet's list the claim was voided with; null when none was given. */
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }
    /** Who last edited the claim (its form or its row's amount entry); null while never edited. */
    public String getEditedBy() { return editedBy; }
    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }
    /** The number of the bulk settle that settled the claim; null when none did. */
    public Integer getBatch() { return batch; }
    public void setBatch(Integer batch) { this.batch = batch; }
    /** The sequence the claim was added in, across every sheet (a clone keeps the claim's own); null for its id. */
    public Long getAddedSeq() { return addedSeq; }
    public void setAddedSeq(Long addedSeq) { this.addedSeq = addedSeq; }
    /** The order the claim was added in, for which rates apply to it (see {@link net.officefloor.hq.app.rate.Rates#pct}):
     *  its added sequence, else its id; null for a claim not yet added. */
    public Long seq() { return addedSeq != null ? addedSeq : id; }
    /** The people the claim is shared with, in the order shared, each with the share of its due they hold. */
    public List<ClaimShare> getShares() { return shares; }
    public void setShares(List<ClaimShare> shares) { this.shares = shares; }
    /** The shares of the claim's due its holders hold, added up (zero when it has none). */
    public BigDecimal sharedTotal() {
        return shares.stream().map(ClaimShare::share).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }
    /** Whether the claim is a correction: its amount is negative. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.util.List;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-mm-dd,
 *  the status as DRAFT, OPEN, PENDING, SETTLED or VOID, the number null when the claim has none, the due
 *  fixed at settling with two decimals, null when it has none (its due is worked out live),
 *  who opened it, null while it has not been opened, whether its person's last statement binds it
 *  and the figure it binds it to (two decimals; null when unbound or bound to n/a), and the number
 *  of the claim a correction corrects (null when it is not a correction), and whether its live
 *  figures round half up (else half to even), by the sheet's policy date, and the due-by fixed when it was added (yyyy-mm-dd), and its status log, oldest first (see {@link ClaimLog}),
 *  and whether it is deferred now and the date it was last deferred until (yyyy-mm-dd; null when it never was), and its proofs count and how many of them are receipts and photos, and the number of the claim it was split off (null when it was not), and the user whose open editor locks it (null when none), and whether it was added while its period was soft-closed, and the last day it was reminded (yyyy-mm-dd; null when it never was), and whether its late charge is waived, and whether it is held, and its external reference (null when none), and its tags (sorted, empty when none) and every tag it has ever carried, and the reason it was voided with (null when none), and its comments, oldest first (see {@link ClaimComments}), and its lines, in the order added (see {@link ClaimLines}), and the number of the bulk settle batch that settled it (null when none), and the sequence it was added in (see {@link Claim#seq}), and the people it is shared with, in the order shared, each with their share (two decimals), and the user its review is assigned to (null when none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects, boolean halfUp, String dueBy, List<String> log,
        boolean deferred, String deferredUntil, int proofs, int proofReceipts, int proofPhotos, String splitFrom, String lockedBy,
        boolean lateEntry, String remindedOn, boolean waived, boolean held, String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<String> comments, List<String> lines, Integer batch, Long seq, List<Share> shares, String reviewAssigned) {

    /** A person holding a share of the claim's due: the share with two decimals. */
    public record Share(long personId, String share) {
    }

    public static ClaimResponse from(Claim claim, Figures figures, List<String> log, List<String> comments, List<String> lines) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() != null ? claim.getDue().toPlainString() : null, claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                claim.getCorrects(), figures.rounding(claim) == RoundingMode.HALF_UP,
                claim.getDueBy().toString(), log, claim.isDeferred(),
                claim.getDeferredUntil() != null ? claim.getDeferredUntil().toString() : null, claim.getProofs(), claim.proofsOf(ProofKind.RECEIPT), claim.getProofPhotos(), claim.getSplitFrom(), claim.getLockedBy(),
                claim.isLateEntry(), claim.getRemindedOn() != null ? claim.getRemindedOn().toString() : null, claim.isWaived(), claim.isHeld(), claim.getRef(),
                split(claim.getTags()), split(claim.getTagsUsed()), claim.getVoidReason(), comments, lines, claim.getBatch(), claim.seq(),
                claim.getShares().stream().map(s -> new Share(s.personId(), s.share().setScale(2).toPlainString())).toList(), claim.getReviewAssigned());
    }

    private static List<String> split(String tags) {
        return tags == null ? List.of() : List.of(tags.split(","));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.settings.Settings;

/** The due-by a claim is fixed with when it is added; it also decides the claim's period. */
public final class DueBy {

    private DueBy() {
    }

    /** The due-by of a claim of `person` dated `date` created now: the terms-th business day after its
     *  date, taking the terms in force on the sheet's today (see `terms`), and skipping every Saturday,
     *  Sunday and holiday on the sheet now. */
    public static LocalDate of(Person person, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(person.getSheetId(), date, terms(person, settings));
    }

    /** The terms a claim of `person` created now is fixed with, each looked up on the day it is created
     *  (the sheet's today), not on its date: the person's own in force then, else those of the grade
     *  they had then, else the sheet's then. */
    public static int terms(Person person, Settings settings) {
        LocalDate created = settings.today(person.getSheetId());
        Integer own = person.termsOn(created);
        return own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(created), created);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim body. `date` is null when none was given: the sheet's today is used.
 *  `corrects` is the number of the claim a correction corrects; null for any other claim.
 *  `ref` is the external reference, trimmed; null when none was given.
 *  `tags` is the claim's tags, each trimmed and lower-cased, repeats dropped, sorted, comma separated; null when none was given. */
public record ClaimValues(BigDecimal amount, LocalDate date, String note, String corrects, String user, String ref, String tags) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** The number a claim gets when it is settled or approved. While the sheet's period numbering from is set and
 *  the sheet's today is on or after it, the claim is numbered within the period its due-by falls in
 *  (<period name>-<n>), or X-<n> when it falls in none; otherwise it takes the next number within
 *  the fiscal year its due-by falls in (FY<yyyy>-<n>, counting from 1 each fiscal year, the sequence
 *  shared across the sheet's tree). */
@Service
public class ClaimNumbers {

    /** The sequence of claims in no period. */
    public static final String NO_PERIOD = "X";

    private final Sheets sheets;
    private final Settings settings;
    private final Periods periods;

    public ClaimNumbers(Sheets sheets, Settings settings, Periods periods) {
        this.sheets = sheets;
        this.settings = settings;
        this.periods = periods;
    }

    public String next(Claim claim) {
        String sheetId = claim.getSheetId();
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            int fy = fiscalYear(claim.getDueBy(), settings.fiscalStartMonth(sheetId));
            return "FY" + fy + "-" + sheets.nextFiscalNumber(sheetId, fy);
        }
        String seq = periods.onSheet(sheetId).stream().filter(p -> p.contains(claim.getDueBy()))
                .map(Period::name).findFirst().orElse(NO_PERIOD);
        return seq + "-" + sheets.nextPeriodNumber(sheetId, seq);
    }

    /** The fiscal year (the yyyy of FY<yyyy>, the calendar year its first day falls in) a date is in. */
    static int fiscalYear(LocalDate date, int startMonth) {
        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
    }
}

