8	 *  A DRAFT can be DELETED, and restored to DRAFT on the same sheet's today; a DELETED claim counts nowhere. */
9	public enum ClaimStatus {
10	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
11	
12	    /** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
13	    public boolean counts() {
14	        return this == OPEN || this == PENDING || this == SETTLED;
15	    }
16	
17	    /** Whether the claim is still open: OPEN, or PENDING (handled like an OPEN one: it goes overdue,
18	     *  bears the late charge and a hold takes it out of the totals). */
19	    public boolean isOpen() {
20	        return this == OPEN || this == PENDING;
21	    }
22	}
