36	/** Moves the claim to the action's status, refusing a change its current status does not allow.
37	 *  Settling (not left PENDING) or approving gives the claim its number when it has none yet (see {@link ClaimNumbers}:
38	 *  the next in the sequence its due-by places it in then); an OPEN, PENDING or REVIEW claim has none (a claim
39	 *  numbered before numbering moved to settlement keeps its number). A voided claim keeps its number (and it is never reused).
40	 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
41	 *  bound it to, else its person's grade's rate in force on the claim's date, plus its late charge then, at least the sheet's floor; with no rate it stays live. Settled as of a date, the figure is its due as it stood at the end of that date instead (see {@link ValidateClaimStatus}). The user who opened a claim, or last edited it, may not settle it.
42	 *  When a clerk settles a claim whose due is over the clerk limit in force (its person's grade's on the sheet's today when one is set, else the sheet's) (a due of n/a is within any
43	 *  limit) it goes PENDING instead, its due not yet fixed (still bound by a statement that binds it); a steward settles anything. Only a steward,
44	 *  or its person's approver, approves a PENDING claim (it settles, its due fixed at its figure then, bound or live, plus its late charge, at least the floor),
45	 *  and never the user who opened it or last edited it; a rejection sends it back to OPEN, still bound by the last
46	 *  statement if that bound it.
47	 *  A claim whose due is above the proof threshold in force on its date (its person's grade's then when
48	 *  one is set, else the sheet's) cannot be settled or
49	 *  approved while it has no proofs, nor while it lacks a proof of each of the sheet's proof kinds (refused before the clerk limit is considered).
50	 *  A claim whose due is above the sheet's note threshold in force on its date cannot be opened while
51	 *  its note is empty.
52	 *  A claim whose due is above the sheet's review threshold in force on its date goes to REVIEW when
53	 *  opened instead of OPEN: it records who opened it. Only a steward reviews it, which opens it.
54	 *  A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
55	 *  Only a steward may void a SETTLED claim, and only while the sheet's today is within 7 days of its
56	 *  settlement (its status log's SETTLED date); its frozen due then leaves every total.
57	 *  A claim due by in a period with a cap cannot be opened while its person already has that many
58	 *  OPEN or PENDING claims due by in it.
59	 *  A claim cannot be opened while its person already has the sheet's maximum of OPEN or PENDING claims.
60	 *  While its person's flag is in force only a steward may open a claim.
61	 *  A claim due by in a closed period cannot change status at all. Opening, settling and voiding are
62	 *  only for the roles the sheet's permission matrix allows (see {@link Settings#allows}).
63	 *  While the sheet's list of void reasons is not empty, a void needs a reason from it, which the
64	 *  claim keeps.
65	 *  A DRAFT claim can be deleted; a DELETED one restored to DRAFT only on the sheet's today it was
66	 *  deleted (its status log's last DELETED date). */
67	public class ApplyClaimStatus {
68	    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a claim. */
69	    static final int SETTLED_VOID_DAYS = 7;
70	
71	    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
72	            Figures figures, ClosedPeriods closedPeriods, Settings settings, ClaimLog log, Sheets sheets,
73	            VoidReasons voidReasons)
74	            throws ClaimStatusRefusedException, PeriodClosedException {
75	        apply(change, claim, claim, numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
76	    }
77	
78	    /** As {@link #apply}, but with the four-eyes rules (who opened or last edited it) and the proof rule
79	     *  judged on {@code judged} rather than on the claim itself (a part-settle judges them on the
80	     *  claim the part was split off, as it stood before the split). */
81	    void apply(ClaimStatusChange change, Claim claim, Claim judged, ClaimNumbers numbers, People people,
82	            Figures figures, ClosedPeriods closedPeriods, Settings settings, ClaimLog log, Sheets sheets,
83	            VoidReasons voidReasons)
84	            throws ClaimStatusRefusedException, PeriodClosedException {
85	        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
86	        if (!change.action().allowedFrom(claim.getStatus())) {
87	            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
88	        }
89	        String perm = change.action() == ClaimAction.OPEN ? "open" : change.action() == ClaimAction.SETTLE ? "settle"
90	                : change.action() == ClaimAction.VOID ? "void" : null;
91	        if (perm != null && !settings.allows(claim.getSheetId(), perm, change.user())) {
92	            throw new ClaimStatusRefusedException("Your role may not " + perm + " a claim");
93	        }
94	        if (change.action() == ClaimAction.OPEN && settings.role(claim.getSheetId(), change.user()) != Role.STEWARD
95	                && people.find(claim.getSheetId(), claim.getPersonId()).isFlagged()) {
96	            throw new ClaimStatusRefusedException("Only a steward can open a claim of a flagged person");
97	        }
98	        if (change.action() == ClaimAction.OPEN && (claim.getNote() == null || claim.getNote().isBlank())) {
99	            BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
100	            if (threshold != null) {
101	                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
102	                BigDecimal due = figures.due(claim, grade);
103	                if (due != null && due.compareTo(threshold) > 0) {
104	                    throw new ClaimStatusRefusedException("A claim whose due is over the note threshold needs a note");
105	                }
106	            }
107	        }
108	        if (change.action() == ClaimAction.OPEN
109	                && closedPeriods.atCap(claim.getSheetId(), claim.getPersonId(), claim.getDueBy())) {
110	            throw new ClaimStatusRefusedException("The person already has as many open claims in the period as its cap allows");
111	        }
112	        if (change.action() == ClaimAction.OPEN && settings.atMaxOpen(claim.getSheetId(), claim.getPersonId())) {
113	            throw new ClaimStatusRefusedException("The person already has as many open claims as the sheet's maximum allows");
114	        }
115	        if (change.action() == ClaimAction.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
116	            LocalDate settled = log.settledOn(claim);
117	            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD || settled == null
118	                    || sheets.today(claim.getSheetId()).isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
119	                throw new ClaimStatusRefusedException("Only a steward can void a settled claim, and only within "
120	                        + SETTLED_VOID_DAYS + " days of its settlement");
121	            }
122	        }
123	        if (change.action() == ClaimAction.RESTORE) {
124	            LocalDate deleted = log.lastOn(claim, ClaimStatus.DELETED);
125	            if (deleted == null || !deleted.equals(sheets.today(claim.getSheetId()))) {
126	                throw new ClaimStatusRefusedException("A deleted claim can be restored only on the day it was deleted");
127	            }
128	        }
129	        String voidReason = null;
130	        if (change.action() == ClaimAction.VOID && !voidReasons.onSheet(claim.getSheetId()).isEmpty()) {
131	            if (change.reason() == null || !voidReasons.has(claim.getSheetId(), change.reason())) {
132	                throw new ClaimStatusRefusedException("A void needs a void reason from the sheet's list");
133	            }
134	            voidReason = change.reason();
135	        }
136	        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
137	            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
138	        }
139	        if (change.action() == ClaimAction.SETTLE && judged.getOpenedBy() != null
140	                && judged.getOpenedBy().equals(change.user())) {
141	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
142	        }
143	        if (change.action() == ClaimAction.SETTLE && change.user().equals(judged.getEditedBy())) {
144	            throw new ClaimStatusRefusedException("The user who last edited a claim cannot settle it");
145	        }
146	        if (change.action() == ClaimAction.APPROVE) {
147	            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
148	                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
149	            }
150	            if (change.user().equals(claim.getEditedBy())) {
151	                throw new ClaimStatusRefusedException("The user who last edited a claim cannot approve it");
152	            }
153	            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD
154	                    && !change.user().equals(people.find(claim.getSheetId(), claim.getPersonId()).getApprover())) {
155	                throw new ClaimStatusRefusedException("Only a steward or the person's approver can approve a pending claim");
156	            }
157	        }
158	        if (change.action() == ClaimAction.REVIEW && settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
159	            throw new ClaimStatusRefusedException("Only a steward can review a claim");
160	        }
161	        boolean review = false;
162	        if (change.action() == ClaimAction.OPEN) {
163	            BigDecimal threshold = settings.reviewThreshold(claim.getSheetId(), claim.getDate());
164	            if (threshold != null) {
165	                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
166	                BigDecimal due = figures.due(claim, grade);
167	                review = due != null && due.compareTo(threshold) > 0;
168	            }
169	        }
170	        BigDecimal due = null;
171	        boolean pending = false;
172	        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
173	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
174	            // Figures.due: from the bound figure when a statement binds the claim (OPEN or PENDING), else live.
175	            due = figures.due(claim, grade);
176	            // Settled as of a date: frozen at its due as it stood at the end of that date.
177	            if (change.on() != null) due = change.onDue();
178	            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
179	            String judgedGrade = people.find(judged.getSheetId(), judged.getPersonId()).gradeOn(judged.getDate());
180	            BigDecimal judgedDue = judged == claim ? due : figures.due(judged, judgedGrade);
181	            BigDecimal threshold = settings.proofThreshold(judged.getSheetId(), judgedGrade, judged.getDate());
182	            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0 && judged.getProofs() == 0) {
183	                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
184	            }
185	            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0) {
186	                for (String kind : settings.proofKinds(judged.getSheetId())) {
187	                    if (judged.proofsOf(kind) == 0) {
188	                        throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof of each kind: " + kind);
189	                    }
190	                }
191	            }
192	            // The person's grade's own limit on the claim's date when one is set, else the sheet's then.
193	            BigDecimal limit = settings.clerkLimit(claim.getSheetId(), grade, claim.getDate());
194	            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
195	                    && java.util.EnumSet.of(Role.CLERK, Role.RESTRICTED).contains(settings.role(claim.getSheetId(), change.user()));
196	        }
197	        claim.setStatus(pending ? ClaimStatus.PENDING : review ? ClaimStatus.REVIEW : change.action().to());
198	        // Settled one at a time: in no batch (a bulk settle sets its batch after this).
199	        if (change.action() == ClaimAction.SETTLE) claim.setBatch(null);
200	        if (change.action() == ClaimAction.VOID) claim.setVoidReason(voidReason);
201	        if (change.action() == ClaimAction.OPEN) claim.setOpenedBy(change.user());
202	        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
203	            claim.setDue(due);
204	            // Numbered at settlement; a claim numbered already (before numbering moved here) keeps its number.
205	            if (claim.getNumber() == null) claim.setNumber(numbers.next(claim));
206	        }
207	    }
208	}
