211	import java.math.BigDecimal;
212	import java.time.LocalDate;
213	import java.time.format.DateTimeParseException;
214	import java.util.Locale;
215	import net.officefloor.hq.app.person.People;
216	import net.officefloor.hq.app.person.Person;
217	import net.officefloor.hq.app.sheet.AsOf;
218	import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
219	import net.officefloor.hq.app.sheet.Sheets;
220	import net.officefloor.hq.app.rollup.Actor;
221	import net.officefloor.plugin.variable.Out;
222	import org.springframework.web.bind.annotation.PathVariable;
223	import org.springframework.web.bind.annotation.RequestBody;
224	
225	/** Binds the body. A settle as of a date works out the claim's due as it stood at the end of that
226	 *  date (as the as-of view does, see {@link AsOf}) here, before the change's transaction: refused
227	 *  when the date is after the sheet's today or the claim did not exist then. */
228	public class ValidateClaimStatus {
229	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
230	            @RequestBody ClaimStatusRequest request, Sheets sheets, AsOf asOf, Claims claims, People people,
231	            Figures figures, Out<ClaimStatusChange> body, Out<Actor> actor)
232	            throws InvalidSheetRequestException, ClaimStatusRefusedException {
233	        String action = request == null || request.action() == null ? "" : request.action().trim();
234	        ClaimAction parsed;
235	        try {
236	            actor.set(new Actor(request.user()));
237	            parsed = ClaimAction.valueOf(action.toUpperCase(Locale.ROOT));
238	        } catch (IllegalArgumentException e) {
239	            throw new InvalidSheetRequestException("Not a claim action (open, settle, approve, reject, review, void, delete or restore): " + action);
240	        }
241	        String reason = request.reason() == null ? "" : request.reason().trim();
242	        if (parsed == ClaimAction.REJECT && reason.isEmpty()) {
243	            throw new InvalidSheetRequestException("A rejection needs a reason");
244	        }
245	        String kept = parsed == ClaimAction.REJECT || (parsed == ClaimAction.VOID && !reason.isEmpty()) ? reason : null;
246	        String onText = request.on() == null ? "" : request.on().trim();
247	        if (parsed != ClaimAction.SETTLE || onText.isEmpty()) {
248	            body.set(new ClaimStatusChange(parsed, request.user(), kept));
249	            return;
250	        }
251	        LocalDate on;
252	        try {
253	            on = LocalDate.parse(onText);
254	        } catch (DateTimeParseException e) {
255	            throw new ClaimStatusRefusedException("A claim can be settled as of a date only: " + onText);
256	        }
257	        if (on.isAfter(sheets.today(sheetId))) {
258	            throw new ClaimStatusRefusedException("A claim cannot be settled as of a date after the sheet's today");
259	        }
260	        // Null: the claim did not exist then; else its due then (n/a when it had none).
261	        Object[] then = asOf.at(sheetId, on, () -> {
262	            Claim claim = claims.find(sheetId, claimId);
263	            if (claim == null) return null;
264	            Person person = people.find(sheetId, claim.getPersonId());
265	            return new Object[] { figures.due(claim, person.gradeOn(claim.getDate())) };
266	        });
267	        if (then == null) {
268	            throw new ClaimStatusRefusedException("A claim cannot be settled as of a date before it existed");
269	        }
270	        body.set(new ClaimStatusChange(parsed, request.user(), kept, on, (BigDecimal) then[0]));
271	    }
272	}
