291	    private static final String COLUMNS = "SELECT id, sheet_id, person_id, amount, claim_date, note, status, number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, proof_photos, split_from, locked_by, late_entry, reminded_on, escalated, waived, held, ref, tags, tags_used, void_reason, edited_by, due_terms, batch, added_seq, review_assigned, "
292	            + "(SELECT LISTAGG(s.person_id || ':' || s.share, ',') WITHIN GROUP (ORDER BY s.id) FROM claim_share s WHERE s.claim_id = claim.id) AS shares, "
