305	    /** The claim with this id on this sheet, or null when there is none. Locks the claim's row for
306	     *  the rest of the transaction, so two changes to one claim at once happen one after the other. */
307	    public Claim find(String sheetId, long id) {
308	        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", Claims::claim, sheetId, id)
309	                .stream().findFirst().orElse(null);
310	    }
