332	     *  already made against it (VOID or DELETED ones, and the claim `ownId` (null: none), left out). */
333	    public BigDecimal remaining(String sheetId, long personId, String number, Long ownId) {
334	        BigDecimal amount = jdbc.query("SELECT amount FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
335	                (rs, i) -> rs.getBigDecimal("amount"), sheetId, personId, number).stream().findFirst().orElse(BigDecimal.ZERO);
336	        BigDecimal corrections = jdbc.queryForObject("SELECT COALESCE(SUM(amount), 0) FROM claim WHERE sheet_id = ? AND person_id = ? AND corrects = ? "
337	                + "AND status NOT IN ('VOID', 'DELETED') AND id <> ?", BigDecimal.class, sheetId, personId, number, ownId != null ? ownId : -1L);
338	        return amount.add(corrections);
