404	    /** The number the sheet's next bulk settle batch takes: one past its last (see {@link
405	     *  net.officefloor.hq.app.sheet.Sheets#lastBatch}), which it then is. */
406	    public int nextBatch(String sheetId) {
407	        Integer last = jdbc.queryForObject("SELECT GREATEST(COALESCE((SELECT MAX(batch) FROM claim WHERE sheet_id = ?), 0), "
408	                + "COALESCE((SELECT last_batch FROM sheet_batch WHERE sheet_id = ?), 0))", Integer.class, sheetId, sheetId);
409	        int next = (last == null ? 0 : last) + 1;
410	        jdbc.update("MERGE INTO sheet_batch (sheet_id, last_batch) KEY (sheet_id) VALUES (?, ?)", sheetId, next);
411	        return next;
412	    }
