414	    /** Keep the claim's newest share: the person holds it of the claim's due. */
415	    public void share(Claim claim, ClaimShare share) {
416	        jdbc.update("INSERT INTO claim_share (sheet_id, claim_id, person_id, share) VALUES (?, ?, ?, ?)",
417	                claim.getSheetId(), claim.getId(), share.personId(), share.share());
418	    }
419	
420	    /** Insert a new claim (assigning its id) or update an existing one. */
421	    public void save(Claim claim) {
422	        if (claim.getId() != null) {
423	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, proof_photos = ?, locked_by = ?, ref = ?, tags = ?, tags_used = ?, void_reason = ?, edited_by = ?, batch = ? WHERE id = ?",
424	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
425	                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
426	                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getProofs(), claim.getProofPhotos(), claim.getLockedBy(), claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(), claim.getEditedBy(), claim.getBatch(), claim.getId());
427	            return;
428	        }
429	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
430	        jdbc.update(con -> {
431	            PreparedStatement ps = con.prepareStatement(
432	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, number, opened_by, split_from, late_entry, ref, tags, tags_used, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
433	                    new String[] { "id" });
434	            ps.setString(1, claim.getSheetId());
435	            ps.setLong(2, claim.getPersonId());
436	            ps.setBigDecimal(3, claim.getAmount());
437	            ps.setDate(4, Date.valueOf(claim.getDate()));
438	            ps.setString(5, claim.getNote());
439	            ps.setString(6, claim.getStatus().name());
440	            ps.setString(7, claim.getCorrects());
441	            ps.setDate(8, Date.valueOf(claim.getDueBy()));
442	            ps.setString(9, claim.getNumber());
443	            ps.setString(10, claim.getOpenedBy());
444	            ps.setString(11, claim.getSplitFrom());
445	            ps.setBoolean(12, claim.isLateEntry());
446	            ps.setString(13, claim.getRef());
447	            ps.setString(14, claim.getTags());
448	            ps.setString(15, claim.getTagsUsed());
449	            ps.setObject(16, claim.getDueTerms(), Types.INTEGER);
450	            return ps;
451	        }, keys);
452	        claim.setId(keys.getKey().longValue());
453	    }
454	
455	    private static Claim claim(ResultSet rs, int i) throws SQLException {
456	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
457	                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
458	                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
459	                rs.getBigDecimal("due"), rs.getString("opened_by"));
460	        claim.setStated(rs.getBoolean("stated"));
461	        claim.setStatedDue(rs.getBigDecimal("stated_due"));
462	        claim.setCorrects(rs.getString("corrects"));
463	        claim.setDueBy(rs.getDate("due_by").toLocalDate());
464	        claim.setProofs(rs.getInt("proofs"));
465	        claim.setProofPhotos(rs.getInt("proof_photos"));
466	        claim.setSplitFrom(rs.getString("split_from"));
467	        claim.setLockedBy(rs.getString("locked_by"));
468	        claim.setLateEntry(rs.getBoolean("late_entry"));
469	        claim.setRef(rs.getString("ref"));
470	        claim.setTagsUsed(rs.getString("tags_used"));
471	        claim.setTags(rs.getString("tags"));
472	        claim.setVoidReason(rs.getString("void_reason"));
473	        claim.setEditedBy(rs.getString("edited_by"));
474	        int terms = rs.getInt("due_terms");
475	        claim.setDueTerms(rs.wasNull() ? null : terms);
476	        int batch = rs.getInt("batch");
477	        claim.setBatch(rs.wasNull() ? null : batch);
478	        long addedSeq = rs.getLong("added_seq");
479	        claim.setAddedSeq(rs.wasNull() ? null : addedSeq);
480	        Date reminded = rs.getDate("reminded_on");
481	        claim.setRemindedOn(reminded != null ? reminded.toLocalDate() : null);
482	        claim.setEscalated(rs.getBoolean("escalated"));
483	        claim.setWaived(rs.getBoolean("waived"));
484	        claim.setHeld(rs.getBoolean("held"));
485	        claim.setReviewAssigned(rs.getString("review_assigned"));
486	        claim.setShares(ClaimShare.parse(rs.getString("shares")));
487	        Date until = rs.getDate("deferred_until");
488	        Date today = rs.getDate("sheet_today");
489	        claim.setDeferredUntil(until != null ? until.toLocalDate() : null);
490	        claim.setDeferred(until != null && today != null && today.toLocalDate().isBefore(until.toLocalDate()));
491	        return claim;
