package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID; a steward may also void a SETTLED claim within 7 days of its settlement.
 *  A DRAFT whose due is above the sheet's review threshold goes REVIEW when opened, until a steward
 *  reviews it to OPEN (or it is voided); a REVIEW claim counts nowhere but in the status counts.
 *  A DRAFT can be DELETED, and restored to DRAFT on the same sheet's today; a DELETED claim counts nowhere. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still open: OPEN, or PENDING (handled like an OPEN one: it goes overdue,
     *  bears the late charge and a hold takes it out of the totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Settling (not left PENDING) or approving gives the claim its number when it has none yet (see {@link ClaimNumbers}:
 *  the next in the sequence its due-by places it in then); an OPEN, PENDING or REVIEW claim has none (a claim
 *  numbered before numbering moved to settlement keeps its number). A voided claim keeps its number (and it is never reused).
 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
 *  bound it to, else its person's grade's rate in force on the claim's date, plus its late charge then, at least the sheet's floor; with no rate it stays live. Settled as of a date, the figure is its due as it stood at the end of that date instead (see {@link ValidateClaimStatus}). The user who opened a claim, or last edited it, may not settle it.
 *  When a clerk settles a claim whose due is over the clerk limit in force (its person's grade's on the sheet's today when one is set, else the sheet's) (a due of n/a is within any
 *  limit) it goes PENDING instead, its due not yet fixed (still bound by a statement that binds it); a steward settles anything. Only a steward,
 *  or its person's approver, approves a PENDING claim (it settles, its due fixed at its figure then, bound or live, plus its late charge, at least the floor),
 *  and never the user who opened it or last edited it; a rejection sends it back to OPEN, still bound by the last
 *  statement if that bound it.
 *  A claim whose due is above the proof threshold in force on its date (its person's grade's then when
 *  one is set, else the sheet's) cannot be settled or
 *  approved while it has no proofs, nor while it lacks a proof of each of the sheet's proof kinds (refused before the clerk limit is considered).
 *  A claim whose due is above the sheet's note threshold in force on its date cannot be opened while
 *  its note is empty.
 *  A claim whose due is above the sheet's review threshold in force on its date goes to REVIEW when
 *  opened instead of OPEN: it records who opened it. Only a steward reviews it, which opens it.
 *  A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
 *  Only a steward may void a SETTLED claim, and only while the sheet's today is within 7 days of its
 *  settlement (its status log's SETTLED date); its frozen due then leaves every total.
 *  A claim due by in a period with a cap cannot be opened while its person already has that many
 *  OPEN or PENDING claims due by in it.
 *  A claim cannot be opened while its person already has the sheet's maximum of OPEN or PENDING claims.
 *  While its person's flag is in force only a steward may open a claim.
 *  A claim due by in a closed period cannot change status at all. Opening, settling and voiding are
 *  only for the roles the sheet's permission matrix allows (see {@link Settings#allows}).
 *  While the sheet's list of void reasons is not empty, a void needs a reason from it, which the
 *  claim keeps.
 *  A DRAFT claim can be deleted; a DELETED one restored to DRAFT only on the sheet's today it was
 *  deleted (its status log's last DELETED date). */
public class ApplyClaimStatus {
    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a claim. */
    static final int SETTLED_VOID_DAYS = 7;

    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
            Figures figures, ClosedPeriods closedPeriods, Settings settings, ClaimLog log, Sheets sheets,
            VoidReasons voidReasons)
            throws ClaimStatusRefusedException, PeriodClosedException {
        apply(change, claim, claim, numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
    }

    /** As {@link #apply}, but with the four-eyes rules (who opened or last edited it) and the proof rule
     *  judged on {@code judged} rather than on the claim itself (a part-settle judges them on the
     *  claim the part was split off, as it stood before the split). */
    void apply(ClaimStatusChange change, Claim claim, Claim judged, ClaimNumbers numbers, People people,
            Figures figures, ClosedPeriods closedPeriods, Settings settings, ClaimLog log, Sheets sheets,
            VoidReasons voidReasons)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        if (!change.action().allowedFrom(claim.getStatus())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
        }
        String perm = change.action() == ClaimAction.OPEN ? "open" : change.action() == ClaimAction.SETTLE ? "settle"
                : change.action() == ClaimAction.VOID ? "void" : null;
        if (perm != null && !settings.allows(claim.getSheetId(), perm, change.user())) {
            throw new ClaimStatusRefusedException("Your role may not " + perm + " a claim");
        }
        if (change.action() == ClaimAction.OPEN && settings.role(claim.getSheetId(), change.user()) != Role.STEWARD
                && people.find(claim.getSheetId(), claim.getPersonId()).isFlagged()) {
            throw new ClaimStatusRefusedException("Only a steward can open a claim of a flagged person");
        }
        if (change.action() == ClaimAction.OPEN && (claim.getNote() == null || claim.getNote().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null) {
                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
                BigDecimal due = figures.due(claim, grade);
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new ClaimStatusRefusedException("A claim whose due is over the note threshold needs a note");
                }
            }
        }
        if (change.action() == ClaimAction.OPEN
                && closedPeriods.atCap(claim.getSheetId(), claim.getPersonId(), claim.getDueBy())) {
            throw new ClaimStatusRefusedException("The person already has as many open claims in the period as its cap allows");
        }
        if (change.action() == ClaimAction.OPEN && settings.atMaxOpen(claim.getSheetId(), claim.getPersonId())) {
            throw new ClaimStatusRefusedException("The person already has as many open claims as the sheet's maximum allows");
        }
        if (change.action() == ClaimAction.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            LocalDate settled = log.settledOn(claim);
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD || settled == null
                    || sheets.today(claim.getSheetId()).isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
                throw new ClaimStatusRefusedException("Only a steward can void a settled claim, and only within "
                        + SETTLED_VOID_DAYS + " days of its settlement");
            }
        }
        if (change.action() == ClaimAction.RESTORE) {
            LocalDate deleted = log.lastOn(claim, ClaimStatus.DELETED);
            if (deleted == null || !deleted.equals(sheets.today(claim.getSheetId()))) {
                throw new ClaimStatusRefusedException("A deleted claim can be restored only on the day it was deleted");
            }
        }
        String voidReason = null;
        if (change.action() == ClaimAction.VOID && !voidReasons.onSheet(claim.getSheetId()).isEmpty()) {
            if (change.reason() == null || !voidReasons.has(claim.getSheetId(), change.reason())) {
                throw new ClaimStatusRefusedException("A void needs a void reason from the sheet's list");
            }
            voidReason = change.reason();
        }
        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        if (change.action() == ClaimAction.SETTLE && judged.getOpenedBy() != null
                && judged.getOpenedBy().equals(change.user())) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (change.action() == ClaimAction.SETTLE && change.user().equals(judged.getEditedBy())) {
            throw new ClaimStatusRefusedException("The user who last edited a claim cannot settle it");
        }
        if (change.action() == ClaimAction.APPROVE) {
            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
            }
            if (change.user().equals(claim.getEditedBy())) {
                throw new ClaimStatusRefusedException("The user who last edited a claim cannot approve it");
            }
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD
                    && !change.user().equals(people.find(claim.getSheetId(), claim.getPersonId()).getApprover())) {
                throw new ClaimStatusRefusedException("Only a steward or the person's approver can approve a pending claim");
            }
        }
        if (change.action() == ClaimAction.REVIEW && settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can review a claim");
        }
        boolean review = false;
        if (change.action() == ClaimAction.OPEN) {
            BigDecimal threshold = settings.reviewThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null) {
                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
                BigDecimal due = figures.due(claim, grade);
                review = due != null && due.compareTo(threshold) > 0;
            }
        }
        BigDecimal due = null;
        boolean pending = false;
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.due: from the bound figure when a statement binds the claim (OPEN or PENDING), else live.
            due = figures.due(claim, grade);
            // Settled as of a date: frozen at its due as it stood at the end of that date.
            if (change.on() != null) due = change.onDue();
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            String judgedGrade = people.find(judged.getSheetId(), judged.getPersonId()).gradeOn(judged.getDate());
            BigDecimal judgedDue = judged == claim ? due : figures.due(judged, judgedGrade);
            BigDecimal threshold = settings.proofThreshold(judged.getSheetId(), judgedGrade, judged.getDate());
            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0 && judged.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0) {
                for (String kind : settings.proofKinds(judged.getSheetId())) {
                    if (judged.proofsOf(kind) == 0) {
                        throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof of each kind: " + kind);
                    }
                }
            }
            // The person's grade's own limit on the claim's date when one is set, else the sheet's then.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId(), grade, claim.getDate());
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && java.util.EnumSet.of(Role.CLERK, Role.RESTRICTED).contains(settings.role(claim.getSheetId(), change.user()));
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : review ? ClaimStatus.REVIEW : change.action().to());
        // Settled one at a time: in no batch (a bulk settle sets its batch after this).
        if (change.action() == ClaimAction.SETTLE) claim.setBatch(null);
        if (change.action() == ClaimAction.VOID) claim.setVoidReason(voidReason);
        if (change.action() == ClaimAction.OPEN) claim.setOpenedBy(change.user());
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
            // Numbered at settlement; a claim numbered already (before numbering moved here) keeps its number.
            if (claim.getNumber() == null) claim.setNumber(numbers.next(claim));
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the body. A settle as of a date works out the claim's due as it stood at the end of that
 *  date (as the as-of view does, see {@link AsOf}) here, before the change's transaction: refused
 *  when the date is after the sheet's today or the claim did not exist then. */
public class ValidateClaimStatus {
    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            @RequestBody ClaimStatusRequest request, Sheets sheets, AsOf asOf, Claims claims, People people,
            Figures figures, Out<ClaimStatusChange> body, Out<Actor> actor)
            throws InvalidSheetRequestException, ClaimStatusRefusedException {
        String action = request == null || request.action() == null ? "" : request.action().trim();
        ClaimAction parsed;
        try {
            actor.set(new Actor(request.user()));
            parsed = ClaimAction.valueOf(action.toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetRequestException("Not a claim action (open, settle, approve, reject, review, void, delete or restore): " + action);
        }
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (parsed == ClaimAction.REJECT && reason.isEmpty()) {
            throw new InvalidSheetRequestException("A rejection needs a reason");
        }
        String kept = parsed == ClaimAction.REJECT || (parsed == ClaimAction.VOID && !reason.isEmpty()) ? reason : null;
        String onText = request.on() == null ? "" : request.on().trim();
        if (parsed != ClaimAction.SETTLE || onText.isEmpty()) {
            body.set(new ClaimStatusChange(parsed, request.user(), kept));
            return;
        }
        LocalDate on;
        try {
            on = LocalDate.parse(onText);
        } catch (DateTimeParseException e) {
            throw new ClaimStatusRefusedException("A claim can be settled as of a date only: " + onText);
        }
        if (on.isAfter(sheets.today(sheetId))) {
            throw new ClaimStatusRefusedException("A claim cannot be settled as of a date after the sheet's today");
        }
        // Null: the claim did not exist then; else its due then (n/a when it had none).
        Object[] then = asOf.at(sheetId, on, () -> {
            Claim claim = claims.find(sheetId, claimId);
            if (claim == null) return null;
            Person person = people.find(sheetId, claim.getPersonId());
            return new Object[] { figures.due(claim, person.gradeOn(claim.getDate())) };
        });
        if (then == null) {
            throw new ClaimStatusRefusedException("A claim cannot be settled as of a date before it existed");
        }
        body.set(new ClaimStatusChange(parsed, request.user(), kept, on, (BigDecimal) then[0]));
    }
}
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Types;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims of each sheet, newest first: by when each was added, or last reassigned to another person. */
@Repository
public class Claims {

    private static final String COLUMNS = "SELECT id, sheet_id, person_id, amount, claim_date, note, status, number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, proof_photos, split_from, locked_by, late_entry, reminded_on, escalated, waived, held, ref, tags, tags_used, void_reason, edited_by, due_terms, batch, added_seq, review_assigned, "
            + "(SELECT LISTAGG(s.person_id || ':' || s.share, ',') WITHIN GROUP (ORDER BY s.id) FROM claim_share s WHERE s.claim_id = claim.id) AS shares, "
            + "(SELECT today FROM sheet WHERE sheet.id = claim.sheet_id) AS sheet_today FROM claim";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY listed DESC", Claims::claim, sheetId);
    }

    /** The claim with this id on this sheet, or null when there is none. Locks the claim's row for
     *  the rest of the transaction, so two changes to one claim at once happen one after the other. */
    public Claim find(String sheetId, long id) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", Claims::claim, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    /** The person's claims, newest first, each locked for the rest of the transaction. */
    public List<Claim> ofPerson(String sheetId, long personId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
                Claims::claim, sheetId, personId);
    }

    /** Unbind every claim of the person a statement binds: each shows its live figure again. */
    public void unbind(String sheetId, long personId) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ? AND stated",
                sheetId, personId);
    }

    /** Whether the person has a SETTLED claim with this number: one a correction may correct. */
    public boolean settled(String sheetId, long personId, String number) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
                Integer.class, sheetId, personId, number);
        return n != null && n > 0;
    }

    /** What remains of the person's SETTLED claim with this number: its amount less the corrections
     *  already made against it (VOID or DELETED ones, and the claim `ownId` (null: none), left out). */
    public BigDecimal remaining(String sheetId, long personId, String number, Long ownId) {
        BigDecimal amount = jdbc.query("SELECT amount FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
                (rs, i) -> rs.getBigDecimal("amount"), sheetId, personId, number).stream().findFirst().orElse(BigDecimal.ZERO);
        BigDecimal corrections = jdbc.queryForObject("SELECT COALESCE(SUM(amount), 0) FROM claim WHERE sheet_id = ? AND person_id = ? AND corrects = ? "
                + "AND status NOT IN ('VOID', 'DELETED') AND id <> ?", BigDecimal.class, sheetId, personId, number, ownId != null ? ownId : -1L);
        return amount.add(corrections);
    }

    /** Whether a claim on the sheet other than `ownId` (null: any) has this reference, without regard to case. */
    public boolean refUsed(String sheetId, String ref, Long ownId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, ownId != null ? ownId : -1L);
        return n != null && n > 0;
    }

    /** The date of the person's claim with this number, or null when there is none. */
    public LocalDate dateOf(String sheetId, long personId, String number) {
        return jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?",
                (rs, i) -> rs.getDate("claim_date").toLocalDate(), sheetId, personId, number)
                .stream().findFirst().orElse(null);
    }

    /** Move the claim to its (new) person: unbound from any statement, and listed as that person's newest claim. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = FALSE, stated_due = NULL, listed = NEXT VALUE FOR claim_listed WHERE id = ?",
                claim.getPersonId(), claim.getNumber(), claim.getId());
    }

    /** Release every editor's lock on the sheet's claims: the sheet's today has changed. */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }

    /** Release the user's locks on the person's other claims: the person's one claim form edits one claim at a time. */
    public void unlockOthers(String sheetId, long personId, String user, long keptId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
                sheetId, personId, user, keptId);
    }

    /** Fix the claim's due-by again, at the date it now has. */
    public void redue(Claim claim) {
        jdbc.update("UPDATE claim SET due_by = ? WHERE id = ?", Date.valueOf(claim.getDueBy()), claim.getId());
    }

    /** Record a due-by set directly, and that it keeps no terms (so a holiday added does not re-fix it). */
    public void setDueBy(Claim claim) {
        jdbc.update("UPDATE claim SET due_by = ?, due_terms = ? WHERE id = ?", Date.valueOf(claim.getDueBy()),
                claim.getDueTerms(), claim.getId());
    }

    /** Record whether the claim is held. */
    public void hold(Claim claim) {
        jdbc.update("UPDATE claim SET held = ? WHERE id = ?", claim.isHeld(), claim.getId());
    }

    /** Record the user the claim's review is assigned to. */
    public void assignReview(Claim claim) {
        jdbc.update("UPDATE claim SET review_assigned = ? WHERE id = ?", claim.getReviewAssigned(), claim.getId());
    }

    /** Record that the claim's late charge is waived. */
    public void waive(Claim claim) {
        jdbc.update("UPDATE claim SET waived = ? WHERE id = ?", claim.isWaived(), claim.getId());
    }

    /** Record the day the claim was last reminded, and whether it has been escalated. */
    public void remind(Claim claim) {
        jdbc.update("UPDATE claim SET reminded_on = ?, escalated = ? WHERE id = ?", Date.valueOf(claim.getRemindedOn()),
                claim.isEscalated(), claim.getId());
    }

    /** The number the sheet's next bulk settle batch takes: one past its last (see {@link
     *  net.officefloor.hq.app.sheet.Sheets#lastBatch}), which it then is. */
    public int nextBatch(String sheetId) {
        Integer last = jdbc.queryForObject("SELECT GREATEST(COALESCE((SELECT MAX(batch) FROM claim WHERE sheet_id = ?), 0), "
                + "COALESCE((SELECT last_batch FROM sheet_batch WHERE sheet_id = ?), 0))", Integer.class, sheetId, sheetId);
        int next = (last == null ? 0 : last) + 1;
        jdbc.update("MERGE INTO sheet_batch (sheet_id, last_batch) KEY (sheet_id) VALUES (?, ?)", sheetId, next);
        return next;
    }

    /** Keep the claim's newest share: the person holds it of the claim's due. */
    public void share(Claim claim, ClaimShare share) {
        jdbc.update("INSERT INTO claim_share (sheet_id, claim_id, person_id, share) VALUES (?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), share.personId(), share.share());
    }

    /** Insert a new claim (assigning its id) or update an existing one. */
    public void save(Claim claim) {
        if (claim.getId() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, proof_photos = ?, locked_by = ?, ref = ?, tags = ?, tags_used = ?, void_reason = ?, edited_by = ?, batch = ? WHERE id = ?",
                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getProofs(), claim.getProofPhotos(), claim.getLockedBy(), claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(), claim.getEditedBy(), claim.getBatch(), claim.getId());
            return;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, number, opened_by, split_from, late_entry, ref, tags, tags_used, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.getSheetId());
            ps.setLong(2, claim.getPersonId());
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            ps.setString(7, claim.getCorrects());
            ps.setDate(8, Date.valueOf(claim.getDueBy()));
            ps.setString(9, claim.getNumber());
            ps.setString(10, claim.getOpenedBy());
            ps.setString(11, claim.getSplitFrom());
            ps.setBoolean(12, claim.isLateEntry());
            ps.setString(13, claim.getRef());
            ps.setString(14, claim.getTags());
            ps.setString(15, claim.getTagsUsed());
            ps.setObject(16, claim.getDueTerms(), Types.INTEGER);
            return ps;
        }, keys);
        claim.setId(keys.getKey().longValue());
    }

    private static Claim claim(ResultSet rs, int i) throws SQLException {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
                rs.getBigDecimal("due"), rs.getString("opened_by"));
        claim.setStated(rs.getBoolean("stated"));
        claim.setStatedDue(rs.getBigDecimal("stated_due"));
        claim.setCorrects(rs.getString("corrects"));
        claim.setDueBy(rs.getDate("due_by").toLocalDate());
        claim.setProofs(rs.getInt("proofs"));
        claim.setProofPhotos(rs.getInt("proof_photos"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLockedBy(rs.getString("locked_by"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRef(rs.getString("ref"));
        claim.setTagsUsed(rs.getString("tags_used"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        claim.setEditedBy(rs.getString("edited_by"));
        int terms = rs.getInt("due_terms");
        claim.setDueTerms(rs.wasNull() ? null : terms);
        int batch = rs.getInt("batch");
        claim.setBatch(rs.wasNull() ? null : batch);
        long addedSeq = rs.getLong("added_seq");
        claim.setAddedSeq(rs.wasNull() ? null : addedSeq);
        Date reminded = rs.getDate("reminded_on");
        claim.setRemindedOn(reminded != null ? reminded.toLocalDate() : null);
        claim.setEscalated(rs.getBoolean("escalated"));
        claim.setWaived(rs.getBoolean("waived"));
        claim.setHeld(rs.getBoolean("held"));
        claim.setReviewAssigned(rs.getString("review_assigned"));
        claim.setShares(ClaimShare.parse(rs.getString("shares")));
        Date until = rs.getDate("deferred_until");
        Date today = rs.getDate("sheet_today");
        claim.setDeferredUntil(until != null ? until.toLocalDate() : null);
        claim.setDeferred(until != null && today != null && today.toLocalDate().isBefore(until.toLocalDate()));
        return claim;
    }
}

