/** A period as the server sends it: its name, its from and to dates (yyyy-mm-dd), inclusive, whether
 *  it is closed and, when it is, the due-total fixed when it was closed and each person's (by person
 *  id; a person not in it, added since, has 0.00) and each person's carried figure fixed then (alike),
 *  and whether it is only soft-closed: its figures
 *  are fixed as by a close, but claims dated in it can still be changed; and its cap on each person's
 *  OPEN or PENDING claims due by in it (null for none). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  closedPersonTotals: Record<string, string>;
  closedPersonCarried: Record<string, string>;
  soft: boolean;
  cap: number | null;
  /** Each person's opening balance for the period, by person id; a person with none is absent. */
  openings: Record<string, string>;
  /** Whether a steward has locked the period: a locked period cannot be reopened. */
  locked: boolean;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date, re-read whenever the sheet is loaded. */
export function usePeriods(sheet: string) {
  const view = useView();
  return useQuery({
    queryKey: viewKey(periodsKey(sheet), view),
    queryFn: () => getJson<Period[]>(viewPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, view)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The fiscal year a date (yyyy-mm-dd) falls in, FY<yyyy>: a fiscal year starts on the first day of
 *  the sheet's fiscal start month (1 to 12) and is named by the calendar year that day falls in. */
export function fiscalYear(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** A fiscal year the server accepts: yyyy. */
export const YEAR = /^\d{4}$/;

/** A period cap the server accepts: a whole number of at least 1. */
export const CAP = /^[1-9]\d{0,8}$/;

/** A date the server accepts: yyyy-mm-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain `date` (yyyy-mm-dd), or undefined when none does. Periods never
 *  overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** The status a claim had at the end of `date` (yyyy-mm-dd), as its status log records it: the last
 *  line dated on or before it; null when the claim was added after it. A claim kept before the log
 *  began (no lines) goes by its status now. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a person's claim counts in a period's due-total: due by in it (its due-by as fixed when it was added), and counted (OPEN, PENDING
 *  or SETTLED) by the status it had at the end of the period's last day — not a deferred one, nor
 *  one open then once the sheet's today reaches the person's retirement date, unless a statement binds it. */
function countsIn(period: Period, person: Person, claim: Claim, today: string, now: boolean): boolean {
  if (claim.personId !== person.id || periodOf([period], claim.dueBy) === undefined || claim.deferred) return false;
  return countedAs(person, claim, now ? claim.status : statusAt(claim, period.to), today);
}

/** Whether a person's claim, with `status`, is counted: OPEN, PENDING or SETTLED, and not one open
 *  once the person is retired, unless a statement binds it (a hold takes nothing out). */
function countedAs(person: Person, claim: Claim, status: ClaimStatus | null, today: string): boolean {
  if (status !== 'OPEN' && status !== 'PENDING' && status !== 'SETTLED') return false;
  if (status === 'SETTLED' || !heldOn(person, claim.date, today)) return true;
  return claim.stated;
}

/** A person's due-total for a period, in cents: the one fixed when the period was closed (0 for a
 *  person added since), else the dues, as shown now, of their claims that count in it (see
 *  `countsIn`: by the status each had at the period's end, or with `now` by its status now), n/a
 *  ones skipped. */
export function personPeriodDueCents(period: Period, person: Person, claims: Claim[], rates: Rate[], floor: FloorOn, late: Late, today: string, now = false): bigint {
  if (period.closed) {
    const fixed = period.closedPersonTotals?.[String(person.id)];
    return fixed === undefined ? 0n : hundredths(fixed);
  }
  return claims
    .filter((c) => countsIn(period, person, c, today, now))
    .reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, claimRateOn(rates, gradeOn(person, c.date), c), late) ?? 0n), 0n);
}

/** A person's carried figure for a period, in cents: the one fixed when the period was closed (0 for
 *  a person added since), else the dues, as shown now, of their claims that
 *  count (as in `countsIn`) which belong, by due-by, to a period ending before this one starts and
